import heapq

def match(orders):
    trades = []

    # order books
    buy_heap = []  # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)

    # order info: id -> dict with side, price, qty, active, arrival
    book = {}

    arrival_counter = [0]

    def next_arrival():
        arrival_counter[0] += 1
        return arrival_counter[0]

    def clean_buy_heap():
        while buy_heap:
            neg_price, arrival, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0 or info['side'] != 'buy':
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell_heap():
        while sell_heap:
            price, arrival, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0 or info['side'] != 'sell':
                heapq.heappop(sell_heap)
            else:
                break

    def match_incoming(side, price, qty, incoming_id):
        # price is None for market order (no limit)
        # returns remaining qty
        remaining = qty

        if side == 'buy':
            while remaining > 0:
                clean_sell_heap()
                if not sell_heap:
                    break
                sell_price, sell_arrival, sell_id = sell_heap[0]
                if price is not None and sell_price > price:
                    break
                # match
                resting_info = book[sell_id]
                trade_qty = min(remaining, resting_info['qty'])
                trades.append([incoming_id, sell_id, sell_price, trade_qty])
                remaining -= trade_qty
                resting_info['qty'] -= trade_qty
                if resting_info['qty'] <= 0:
                    resting_info['active'] = False
                    heapq.heappop(sell_heap)
        else:  # side == 'sell'
            while remaining > 0:
                clean_buy_heap()
                if not buy_heap:
                    break
                neg_price, buy_arrival, buy_id = buy_heap[0]
                buy_price = -neg_price
                if price is not None and buy_price < price:
                    break
                resting_info = book[buy_id]
                trade_qty = min(remaining, resting_info['qty'])
                trades.append([buy_id, incoming_id, buy_price, trade_qty])
                remaining -= trade_qty
                resting_info['qty'] -= trade_qty
                if resting_info['qty'] <= 0:
                    resting_info['active'] = False
                    heapq.heappop(buy_heap)

        return remaining

    for order in orders:
        op = order[0]

        if op == 'limit':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, price, qty, oid)

            arrival = next_arrival()
            book[oid] = {
                'side': side,
                'price': price,
                'qty': remaining,
                'active': remaining > 0,
                'arrival': arrival
            }

            if remaining > 0:
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, arrival, oid))
                else:
                    heapq.heappush(sell_heap, (price, arrival, oid))

        elif op == 'ioc':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, price, qty, oid)
            # discard remainder, don't add to book
            book[oid] = {
                'side': side,
                'price': price,
                'qty': 0,
                'active': False,
                'arrival': next_arrival()
            }

        elif op == 'market':
            _, oid, side, qty = order
            remaining = match_incoming(side, None, qty, oid)
            book[oid] = {
                'side': side,
                'price': None,
                'qty': 0,
                'active': False,
                'arrival': next_arrival()
            }

        elif op == 'cancel':
            _, oid = order
            if oid in book:
                book[oid]['active'] = False

    return trades

